      "page": 75,
      "name": "The TowerTHREE",
      "omens": [
        "Marching across a barren moor, the Bolt Knight escorts labourers in carts. They are being taken to the site of the Tower, where more efforts are needed.",
        "A dozen great birds of burden haul huge blocks across the Realm. A wake of torn earth. Tower guards escort on horseback.",
        "A stairway in the wilds, dreamlike visions to any who ascend (see opposite). At the top, a clear view of the Tower, complete on the horizon.",
        "Black clouds and thunder, but no rain. Crackling lightning turns to bolts, sparking fires across the Realm. This does not end until the Tower falls.",
        "A titanic thunderclap and dazzling bolt of lightning. The Tower begins to fall and cannot be stopped. The thunder and lightning continue.",
        "With a swell of thunder all tower-like structures in the Realm are shaken, grand or humble. With a final clap they all fall. The clouds clear."
      ],
      "cast": "Bolt Knight, Berech of the Tower\nVIG 12, CLA 17, SPI 9, 7 GD\nA3 (mail, shimmering plate, helm)\nCruel partisan (d10 long +d10 vs mounted) \nHatred for anything less than perfection.\nGreat Bird of Burden, Wazzletard\nVIG 17, CLA 10, SPI 4, 4 GD\nA2 (huge body)\nTrample and tear (2d10)\nEasily startled, longs for human approval.\nTower Guards\nVIG 12, CLA 10, SPI 7, 4 GD\nA2 (mail, helm)\nPolearms (d10 long)\nCraving purpose, to be part of something big.In the tapestry of ages, stretching ever forth\nThe spiteful spirit of the land shows our follies' worth\nDREAMLIKE VISIONS\nForm Content\n1 Frozen Regrets (l ose d6 SPI)\n2 Abstract Hardship (l ose d6 VIG )\n3 Non-visual Fear ( lose d6 CLA )\n4 Ghostly Pride (restore SPI)\n5 Melodramatic Comfort (restore VIG)\n6 Watery Guidance (restore CLA )Tower",
      "landmarks": {
        "Dwelling": "Open market",
        "Sanctum": "Smouldering geyser",
        "Monument": "Buried library",
        "Hazard": "Spike rocks",
        "Curse": "Sulphur stink",
        "Ruin": "Ash pit"
      }
