      "name": "The ToadFIVE",
      "omens": [
        "A caravan of wagons, fat donkeys hauling thick logs, escorted by twelve warty guards. They are respectful to Knights, but urge the need for haste, delivering materials for the Toad's castle.",
        "Two scouts, searching for news of the Toad. They hear his castle has been built.",
        "The Toad's pet, a monstrous slug, is being delivered to his castle in chains. Six warty guards struggle with the task, asking for help. The Toad is grateful for aid given.",
        "Nestled among thorns, a scroll with green ribbon. It reads \"the Toad commends your service\". Anybody reading it feels sickly sweet, as if filled with honey. They choke and sputter syrupy spittle, losing d8 VIG.",
        "A lone warty guard, delivering a gift to one of the Knights (see opposite). Its curse manifests when the item is used, which the guard encourages the Knight to do later. The curse lasts an entire Season.",
        "Twelve warty guards ride forward, demanding the Knights visit the Toad. They must swear to him or die."
      ],
      "cast": "The Toad, the Fat Lord, Born to Rule\nVIG 12, CLA 5, SPI 16, 5 GD\nA4 (blubbersome body)\nGrab and bite (d10), charming voice\nWarty Guards, led by Jabeck\nVIG 12, CLA 10, SPI 8, 5 GD\nA3 (froghelm, mail, rotund plate)\nBow (d6 long), halberd (d10 long)\nFearful look, professional manner.\nBlotch, Beloved Pet to the Toad\nVIG 17, CLA 5, SPI 2, 5 GD\nA4 (monstrous sluglike body)\nSlobbering maw (3d8)\nAlways sad, always hungry.\nWants to be released.In honeyed words a fat and charmsome lord\nIn poisoned gifts a bloaty malice stirred\nBALEFUL GIFTS\nGift Curse\n1 Apple pie Deathly sleep \n2 Froghelm (A1) Loss of speech\n3 Wooden flute Hideous face\n4 Silver mirror Loss of vision\n5 Woollen scarf Total memory loss\n6 Copper mug Loss of hearingToad",
