      "d6": 6,
      "d12": 10,
      "page": 167,
      "name": "The Cave",
      "omens": [
        "A wide cave mouth looms from a vine- cloaked cliff. It seems empty, but echoes sound slightly altered.",
        "Three iron pilgrims attempt to seal the cave, claiming it can only cause harm.",
        "The Cave, a familiar shape and echo. This time a glow emanates from within, revealing 3 useful crystals (see opposite).",
        "The Cave appears again, on a new cliff face, the word \"gold\" echos from within. Anybody entering awakens the beast of solid darkness, which only fights to prevent entry to the Cave. Beyond the beast lies a heavy coffer of gold.",
        "The Cave appears on a great boulder, now with eye-like holes and tooth-like stalactites. It slowly speaks, granting one question to each Knight present. It knows all and answers to the best of its ability.",
        "A towering figure strides out of a shadow, like folds of material darkness. He is the Debt Collector, here to take payment for the Cave. He accepts anything of value, and tries to kill those who won't pay."
      ],
      "cast": "Beast of Solid Darkness\nVIG 12, CLA 12, SPI 7, 8 GD\nA3 (darkness hardened to iron)\nBlade out of darkness (3d10) \nor burst of un-light (d8 blast)\nIron Pilgrims, Lymon, Sid, Hayma\nVIG 12, CLA 10, SPI 13, 3 GD\nRobes and chains, blacksmith tools \nDebt Collector, Ambralleon\nVIG 16, CLA 16, SPI 7, 8 GD\nA2 (shadow form, cold plates)\nBlack spear (2d8 hefty, can be thrown and \ncalled back into his hand). Can Smite. A weary soul discerns no truth or lie\nAn eager heart asks neither what or why\nUSEFUL CRYSTALS\nAppearance Power when Broken\n1 Flickering grey d10 blast of lightning\n2 Milky whiteReleases horrifying but \nharmless ghosts\n3 Dull ochreWinter arrives \nimmediately\n4 Pale mauveOpen up a flaming pit \n(d10) in the ground\n5 Swirling turquoise Vision of a useful truth\n6 Pulsing crimson Plants grow rapidly",
